  {id=416,name="Perfect Adaptation",tier=2,rarity="Epic",category="Epic Defense",description="Repeated exposure builds temporary adaptation profiles against damage categories and CC subtypes.\n\nRank V caps: 15% reduction vs one damage category, 25% duration reduction vs one CC subtype; lower ranks 6/8/10/12/15 and 10/14/18/22/25.\n\nOnly 1/1/2/2/2 damage profiles + 1 CC profile active; weaker profiles decay first.",requirement="",source="tier2:data/source/tier2_v0_1/Tier2_240_Skills.csv"},
  {id=417,name="Blood-for-Power Engine",tier=2,rarity="Epic",category="Epic Conversion",description="Taking or voluntarily paying health fills a Blood reservoir; every 8% max-health accumulated grants 1 stack.\n\nEach stack increases damage/healing by 2/3/4/5/6%; max 2/3/4/5/5.\n\nReceiving healing above 80% health drains 1 stack per 5% max HP restored; 15 sec inactivity decays.",requirement="",source="tier2:data/source/tier2_v0_1/Tier2_240_Skills.csv"},
  {id=418,name="Adaptive Spellblade",tier=2,rarity="Epic",category="Epic Hybrid",description="Weapon hits build Martial stacks; damaging/healing spells build Mystic stacks. At 3 of each, gain Fusion.\n\nFusion converts 10/15/20/25/30% of the lower of AP or SP into the other stat as bonus and grants +5/7/9/11/15% hybrid damage/healing.\n\nFusion lasts 8 sec; using only one side causes its opposite stacks to decay.",requirement="",source="tier2:data/source/tier2_v0_1/Tier2_240_Skills.csv"},
  {id=419,name="Perfect Evolution",tier=2,rarity="Legendary",category="Legendary Adaptive",description="The system tracks your dominant recent combat behavior across offense, defense, healing, pets, and movement; sustained dominance builds an Evolution state.\n\nRank V: dominant state grants ~18% primary effectiveness to that behavior plus a secondary 8% complementary bonus; lower ranks ~8/10/12/15/18%.\n\nBehavior must remain dominant for 12 sec to enter; shifting dominance for 8 sec transitions state. Only one state active.",requirement="",source="tier2:data/source/tier2_v0_1/Tier2_240_Skills.csv"},
  {id=420,name="Evolutionary Instinct",tier=2,rarity="Mythic",category="Mythic Adaptive",description="Repeated combat behavior builds Affinity scores (Fire, Frost, Physical, Guardian, Predator, Restoration, Summoner, etc.). When one Affinity strongly dominates, manifest its evolved state.\n\nRank V example states: +25% primary Affinity effectiveness, +10% secondary mechanic, and a bespoke minor rider; lower ranks 10/14/18/22/25%.\n\nAffinity decays gradually when behavior changes; new dominant Affinity replaces the old state after a transition threshold. No permanent choice.",requirement="",source="tier2:data/source/tier2_v0_1/Tier2_240_Skills.csv"},
  {id=421,name="Patient Aim",tier=3,rarity="Common",category="Critical / Precision",description="When an eligible direct ability fails to crit, your next different direct ability within 6 sec gains +4/5/6/8/10% Crit Chance. Does not stack.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
  {id=422,name="Guarded Opening",tier=3,rarity="Common",category="Critical / Precision",description="Dodging, parrying, or blocking grants your next direct offensive ability within 5 sec +5/6/7/8/10% Crit Chance. 4-sec ICD.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
  {id=423,name="Disruptive Precision",tier=3,rarity="Common",category="Critical / Precision",description="Successfully interrupting an enemy grants your next direct damage or healing ability within 8 sec +6/8/10/12/15% Crit Chance. 8-sec ICD.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
  {id=424,name="Keen Pursuit",tier=3,rarity="Common",category="Critical / Precision",description="Moving at least 8 yd within 3 sec causes your next direct attack/spell within 5 sec to gain +3/4/5/6/8% Crit Chance. 6-sec ICD.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
  {id=425,name="Critical Ward",tier=3,rarity="Common",category="Critical / Precision",description="Landing a direct critical strike grants an absorb equal to 0.50/0.65/0.80/1.00/1.25% Max Health for 8 sec. 8-sec ICD.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
