  {id=439,name="Focused Mending",tier=3,rarity="Uncommon",category="Critical / Precision",description="Critically healing a target below 50% Health grants an absorb equal to 5/6/7/8/10% of the effective healing done for 8 sec.",requirement="HEAL",source="tier3:T3_ALL_SKILLS_421_750.csv"},
  {id=440,name="Exacting Counterstrike",tier=3,rarity="Uncommon",category="Critical / Precision",description="After you dodge, parry, or block, your next critical strike within 6 sec deals 8/10/12/15/18% additional final damage. One charge; does not stack.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
  {id=441,name="Fracture Cascade",tier=3,rarity="Rare",category="Critical / Precision",description="Critting an enemy carrying at least 3 harmful effects causes 20/25/30/35/40% of the final critical damage to strike up to 2 nearby enemies. 8-sec ICD.",requirement="",source="tier3:T3_ALL_SKILLS_421_750.csv"},
